// ***************
// Filename: py_stream_port_top.sv
// Author: FPGA Cores 4 U
// Description: py_stream_port with its AXI4-Lite register interface, the
//   block designs and testbenches instantiate: the register map
//   py_stream_port_regs (u_regs, src/include/py_stream_port_regs.sv, ID
//   "PORT", VERSION and DATE at 0x00-0x08, the registers from 0x10) and the
//   logic py_stream_port (u_core, src/py_stream_port.sv), joined by the
//   register interface py_stream_port_regs_if (u_regs_if). Generated by
//   ip/scripts/regmap_gen.py from py_stream_port_regs.json and the ports of
//   py_stream_port: regenerate after changing either. Clock - aclk. Reset -
//   synchronous active low aresetn.
// Date: 2026-10-16
module py_stream_port_top #(
  parameter int DATA_W = 8,
  parameter int TX_DEPTH = 16,
  parameter int RX_DEPTH = 16
) (
  input  logic aclk,
  input  logic aresetn,
  // s_axil: axil_if.slave (ip/shared/src/interfaces/axil_if.sv), ADDR_W = 8
  axil_if.slave s_axil,
  // m_axis: axis_if.master (ip/shared/src/interfaces/axis_if.sv), DATA_W = DATA_W
  axis_if.master m_axis,
  // s_axis: axis_if.slave (ip/shared/src/interfaces/axis_if.sv), DATA_W = DATA_W
  axis_if.slave s_axis,
  output logic irq_o
);
  // register interface between the register map and the logic
  py_stream_port_regs_if u_regs_if ();

  py_stream_port_regs u_regs (
    .aclk,
    .aresetn,
    .s_axil(s_axil),
    .r(u_regs_if)
  );
  py_stream_port #(
    .DATA_W(DATA_W),
    .TX_DEPTH(TX_DEPTH),
    .RX_DEPTH(RX_DEPTH)
  ) u_core (
    .aclk,
    .aresetn,
    .m_axis,
    .s_axis,
    .irq_o,
    .regs(u_regs_if)
  );
endmodule
